<script setup lang="ts">
import { inject } from 'vue'
import Icon from '../../src/components/visual/ArchiveIcon.vue'
import Select from '../../src/components/ui/StudioSelect.vue'
import { previewKey, styleOptions } from './usePreview'
const p = inject(previewKey)!
const tabs = [{id:'render',name:'绘制'},{id:'image',name:'图像'},{id:'prompt',name:'提示词'},{id:'tasks',name:'任务'}]
</script>
<template>
  <aside class="inspector side-panel" aria-label="绘制工具">
    <div class="panel-heading"><div><span class="eyebrow">落笔</span><h2>绘制工具</h2></div><span class="mode-label">{{ p.s.expert ? '专家模式' : '场景模式' }}</span></div>
    <div class="panel-tabs" role="group" aria-label="参数分类"><button v-for="t in tabs" :key="t.id" :aria-pressed="p.s.inspector===t.id" @click="p.s.inspector=t.id">{{t.name}}<span v-if="t.id==='tasks' && p.busy" class="count">1</span></button></div>
    <div class="panel-scroll">
      <template v-if="p.s.inspector==='render'">
        <section class="form-section first"><label class="field-label">出图引擎</label><div class="segmented" role="group" aria-label="出图引擎"><button :aria-pressed="p.s.render.family==='anima'" :disabled="p.busy" @click="p.selectEngine('anima')">Anima</button><button :aria-pressed="p.s.render.family==='krea2'" :disabled="p.busy" @click="p.selectEngine('krea2')">Krea 2</button></div>
          <label class="field-label" for="model">基础模型</label><Select id="model" :model-value="p.s.render.modelId" label="基础模型" :disabled="p.busy" :options="[{value:p.s.render.modelId,label:p.model.label+(p.s.compare ? ' · 模型未安装' : '')}]" />
          <p class="hint"><Icon name="info" />展示已登记模型名称；连接状态为模拟。</p>
        </section>
        <section class="form-section"><div class="section-heading"><h3>画幅</h3><span class="mono muted">{{ p.s.render.width }} × {{ p.s.render.height }}</span></div>
