      <template v-else><section class="form-section first"><div class="section-heading"><h3>当前任务</h3><span class="demo-badge">模拟</span></div><div class="task-card"><Icon :name="p.busy ? 'spark' : 'info'" /><strong>{{p.busy ? '绘制中 · 46%' : '暂无运行中的任务'}}</strong><p>{{p.scene.title}} · {{p.s.ratio.replace('x',' × ')}}</p><p class="hint">进度固定用于设计预览，没有真实任务。</p><button v-if="p.busy" @click="p.generate()">停止绘制</button></div><label class="check-row"><input v-model="p.s.autoSave" type="checkbox" />完成后自动入册（模拟）</label><button class="subtle-button wide" @click="p.notify('批量生成仅展示入口，本页不会创建任务。')">批量生成</button></section></template>
